export const login = AsyncHandler(async (req: Request, res: Response) => {
  const { email } = req.body as LoginInput;

  const user = await UserServices.findUserByEmail(email);

  if (!user.isActive) {
    throw new BadRequestError('Account is deactivated');
  }

  if (!user.emailVerified) {
    throw new BadRequestError('Please verify your email address before logging in');
  }

  await UserServices.updateLastLogin(Number(user.id));

  const { accessToken } = await Token.attachTokenToRequest(user.id, res);

  res.json(formatResponse({ user, accessToken }, 'Login successful'));
});

static async sendVerificationEmail({
  email,
  name,
  token,
}: {
  email: string;
  name: string;
  token: string;
}) {
  const verificationLink = `${this.clientUrl}/api/v1/auth/verify-email?token=${token}`;

  const mailOptions = {
    from: this.fromEmail,
    to: email,
    subject: 'Verify Your Email Address - Task Flow',
    html: `
              <div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">
                  <h2 style="color: #333;">Welcome to Task Flow!</h2>
                  <p>Hi ${name},</p>
                  <p>Thank you for signing up. Please verify your email address by clicking the button below:</p>
                  <p style="text-align: center; margin: 20px 0;">
                      <a href="${verificationLink}" 
                         style="background-color: #3498db; color: white; padding: 10px 20px; 
                                text-decoration: none; border-radius: 5px; display: inline-block;">
                         Verify Email Address
                      </a>
                  </p>
                  <p>Or copy and paste this link in your browser:</p>
                  <p style="word-break: break-all; color: #666; font-size: 14px;">${verificationLink}</p>
                  <p>This link will expire in 24 hours.</p>
                  <p>If you did not create an account, please ignore this email.</p>
                  <p>Thank you,<br>The Task Flow Team</p>
              </div>
          `,
  };

  await this.transporter.sendMail(mailOptions);
}

});

export const resendVerificationEmail = AsyncHandler(async (req: Request, res: Response) => {
  const { email } = req.body as { email: string };

  if (!email) {
    throw new BadRequestError('Email is required');
  }

  const user = await UserServices.findUserByEmail(email);

  if (!user) {
    // For security, don't reveal if user exists
    res.json(
      formatResponse(
        null,
        'If the email exists and is not verified, a verification email has been sent.'
      )
    );
    return;
  }

  if (user.emailVerified) {
    throw new BadRequestError('Email is already verified');
  }

  // Delete any existing verification tokens for this user
  await db.delete(tokens).where(
    eq(tokens.userId, user.id) && eq(tokens.type, 'email_verification')
  );

  // Generate new verification token
  const verificationToken = crypto.randomBytes(32).toString('hex');
  const expiresAt = new Date(Date.now() + 24 * 60 * 60 * 1000); // 24 hours expiry

  // Store new verification token in database
  await db.insert(tokens).values({
    userId: user.id,
    token: verificationToken,
    type: 'email_verification',
    expiresAt,
  });

  // Set verification token as HTTP-only cookie
  res.cookie('verificationToken', verificationToken, {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'strict',
    maxAge: 24 * 60 * 60 * 1000, // 24 hours
  });

  // Send verification email
  await EmailService.sendVerificationEmail({
    email: user.email,
    name: user.firstName,
    token: verificationToken,
  });

  res.json(
    formatResponse(
      null,
      'If the email exists and is not verified, a verification email has been sent.'
    )
  );
});

