export const logout = AsyncHandler(async (req: Request, res: Response) => {
  res.clearCookie('accessToken');
  res.clearCookie('refreshToken');
  res.clearCookie('verificationToken');

  res.json(formatResponse(null, 'Logout successful'));
});

import { z } from 'zod';

export const registerSchema = z.object({
  email: z.email('Invalid email format'),
  firstName: z.string().min(1, 'First name is required').max(100),
  lastName: z.string().min(1, 'Last name is required').max(100),
  role: z.enum(['user', 'agent']).optional().default('user'),
});

export const loginSchema = z.object({
  email: z.email('Invalid email format'),
});

export const forgotPasswordSchema = z.object({
  email: z.email('Invalid email format'),
});

export const resetPasswordSchema = z.object({
  token: z.string().min(1, 'Reset token is required'),
  password: z.string().min(6, 'Password must be at least 6 characters'),
});

export const resendVerificationSchema = z.object({
  email: z.email('Invalid email format'),
});

export type RegisterInput = z.infer<typeof registerSchema>;
export type LoginInput = z.infer<typeof loginSchema>;
export type ForgotPasswordInput = z.infer<typeof forgotPasswordSchema>;
export type ResetPasswordInput = z.infer<typeof resetPasswordSchema>;
export type ResendVerificationInput = z.infer<typeof resendVerificationSchema>;

import CustomError from '../utils/errors';
import { Request, Response, NextFunction } from 'express';
import { validationResult, ValidationChain } from 'express-validator';
import { z } from 'zod';

export const validate = (validations: ValidationChain[]) => {
  return async (
    req: Request,
    res: Response,
    next: NextFunction
  ): Promise<void> => {
    try {
      await Promise.all(validations.map((validation) => validation.run(req)));

      const errors = validationResult(req);

      if (!errors.isEmpty()) {
        const error = new CustomError({
          message: `Validation error: ${errors
            .array()
            .map((err) => `${err.type}: ${err.msg}`)
            .join(', ')}`,
          statusCode: 400,
        });
        (error as any).errors = errors.array();
        throw error;
      }

      next();
    } catch (error) {
      next(error);
    }
  };
};

export const validateSchema = (schema: z.ZodSchema) => {
  return (req: Request, res: Response, next: NextFunction): void => {
    try {
      schema.parse(req.body);
      next();
    } catch (error) {
      if (error instanceof z.ZodError) {
        const validationError = new CustomError({
          message: `Validation error: ${error.errors
            .map((err) => `${err.path.join('.')}: ${err.message}`)
            .join(', ')}`,
          statusCode: 400,
        });
        (validationError as any).errors = error.errors;
        next(validationError);
      } else {
        next(error);
      }
    }
  };
};

